ON CONFLICT (icao) DO UPDATE SET
    iata            = coalesce(refdata.airports.iata, excluded.iata),
    city            = coalesce(refdata.airports.city, excluded.city),
    latitude        = coalesce(refdata.airports.latitude, excluded.latitude),
    longitude       = coalesce(refdata.airports.longitude, excluded.longitude),
    elevation_ft    = coalesce(refdata.airports.elevation_ft, excluded.elevation_ft),
    region          = excluded.region,
    traffic_level   = excluded.traffic_level,
    fuel_type       = excluded.fuel_type,
    fire_category   = excluded.fire_category,
    operating_hours = excluded.operating_hours,
    slot_required   = excluded.slot_required,
    slot_regime     = excluded.slot_regime,
    restrictions    = excluded.restrictions,
    runway_remark   = excluded.runway_remark;

